const D = { density: .55, energy: .6, hue: 335, speed: 1, scale: 1, warp: .25, x: .5, y: .46, seed: 0, style: 'gloss', act: 'cruise' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const hz = cl(P.y, .28, .72) * height;
const cx = cl(P.x, .05, .95) * width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t, 1.7) * groundH;
const hwOf = t => width * (.045 + t * .95) * .5 * P.scale;
const NR = Math.round(8 + P.density * 20);
const NC = Math.round(5 + P.density * 13);
const H = P.hue;
// three candy hues rotating around the wheel from base hue
const CH = [H, (H+175)%360, (H+265)%360];

S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.6);

// real-time scroll (integrate seconds)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.5 + .8*K.intensity);
if (P.act === 'pulse') sp *= 1 + 1.0*kick;
if (P.act === 'tide')  sp *= .35 + .95*(.5 + .5*Math.sin(K.t*.055 + K.section*.9));
S.scroll = (S.scroll||0) + dt*sp*.55;
const scroll = S.scroll;

// ---- cached plane base (sky + ground wash + vignette) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 54;
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz;
    let h,s,b;
    if (sty==='liquorice'){ h=0; s=0; b=90-40*f; }
    else if (sty==='neon'){ h=H; s=45; b=5+7*f; }
    else if (sty==='halftone'){ h=H; s=8; b=92-6*f; }
    else { h=(H+30*f)%360; s=30-16*f; b=70+18*f; }   // gloss pastel sky
    g.fill(h,cl(s,0,90),cl(b,3,90),100); g.rect(0,y,width,hz/STR+1);
  }
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR);
    let h,s,b;
    if (sty==='liquorice'){ h=0; s=0; b=cl(88-70*Math.pow(t,.7),12,90); }
    else if (sty==='neon'){ h=H; s=40; b=5+10*t; }
    else if (sty==='halftone'){ h=H; s=6; b=cl(94-26*t,60,94); }
    else { h=(H+18*t)%360; s=22+10*t; b=cl(86-40*Math.pow(t,.8),30,90); }
    g.fill(h,cl(s,0,90),b,100); g.rect(0,y,width,(y2-y)+1);
  }
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- live scrolling checker cells ----
const warp = P.warp;
const xAt = (u, hw) => { const d=(u-.5); return cx + d*2*hw*(1 + warp*.9*d*d*4); };
push(); noStroke();
for (let r=0; r<NR; r++){
  const t0=r/NR, t1=(r+1)/NR;
  const y0=yOf(t0), y1=yOf(t1), hw0=hwOf(t0), hw1=hwOf(t1);
  const rr = Math.floor(r + scroll);
  const near = (t0+t1)*.5;
  for (let c=0; c<NC; c++){
    const u0=c/NC, u1=(c+1)/NC;
    const p = ((rr + c) % 2 + 2) % 2;
    const p3 = ((rr + c) % 3 + 3) % 3;
    const x0a=xAt(u0,hw0), x0b=xAt(u1,hw0), x1a=xAt(u0,hw1), x1b=xAt(u1,hw1);
    if (sty==='liquorice'){
      const b = p===0 ? 6 : 96;
      fill(0,0,b,100);
      quad(x0a,y0,x0b,y0,x1b,y1,x1a,y1);
    } else if (sty==='halftone'){
      const on = p===0;
      const ch = CH[p3];
      const cxm=(x0a+x0b+x1a+x1b)/4, cym=(y0+y1)/2;
      const cellW=Math.abs(x0b-x0a);
      const rad = (on ? .46 : .16) * cellW * (1 + .3*near);
      fill(ch, on?68:60, on?96:88, 100);
      ellipse(cxm, cym, rad*2, rad*2);
    } else if (sty==='neon'){
      if (p===0){ const ch=CH[p3];
        noFill(); stroke(ch,85,100, (30+55*near)*(.6+.5*glow)); strokeWeight(.7+near*2);
        quad(x0a,y0,x0b,y0,x1b,y1,x1a,y1); noStroke(); }
    } else { // gloss candy
      const ch = CH[p3];
      const shade = p===0 ? 1 : .82;
      fill(ch, (34+8*near), cl((92-26*near)*shade,20,96), 100);
      quad(x0a,y0,x0b,y0,x1b,y1,x1a,y1);
    }
  }
}
pop();

// ---- specular sheen sweep (real-time, all styles) ----
push(); blendMode(ADD); noStroke();
const sweep = (Math.sin(K.t*.35) * .5 + .5);            // 0..1 continuous
for (let r=0;r<NR;r++){ const t0=r/NR, near=t0;
  const y0=yOf(t0), y1=yOf((r+1)/NR), hw0=hwOf(t0), hw1=hwOf((r+1)/NR);
  const band = Math.exp(-Math.pow((near - sweep)*3.4, 2));   // gaussian highlight
  if (band < .04) continue;
  const b = sty==='liquorice' ? 45 : 95;
  fill(sty==='neon'?H:0, 0, b, cl(band*30*(.5+.9*glow),0,34));
  quad(cx-hw0,y0,cx+hw0,y0,cx+hw1,y1,cx-hw1,y1);
}
pop();

// ---- horizon candy glow pulse (partial-frame, safe) ----
push(); blendMode(ADD); noStroke();
const flare=(kick*.6+K.swell*.35)*glow;
for(let i=0;i<5;i++){ const rr=(5-i)*groundH*.045*(1+flare);
  fill(CH[Math.floor(K.section)%3], sty==='liquorice'?0:55, sty==='liquorice'?90:98, 4+9*flare);
  rect(0, hz-rr*.4, width, rr); }
pop();

// ---- sparkles rising (continuous) ----
const NP = Math.round(P.density * 46);
push(); blendMode(ADD); noStroke();
for (let i=0;i<NP;i++){
  const lane=fr(i*4), spd=.4+fr(i*4+1)*1.0;
  let prog=(fr(i*4+2)+scroll*.12*spd)%1;
  const t=1-prog; if(t<=.02) continue;
  const y=yOf(t), hw=hwOf(t);
  const x=cx+(lane*2-1)*hw*.96;
  const sz=(1.4+4.5*t)*(1+.5*S.tre);
  fill(sty==='liquorice'?0:CH[i%3], sty==='liquorice'?0:50, 100, Math.min(40,(9+30*t)*(.5+.9*glow)));
  ellipse(x,y,sz,sz);
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
